// Fake employee directory. Replace / extend as needed - this is the ONLY place employee data lives.
const employees = [
  { employee_id: "E1001", email: "aisha.khan@acmecorp.com", name: "Aisha Khan", department: "Sales" },
  { employee_id: "E1002", email: "ravi.mehta@acmecorp.com", name: "Ravi Mehta", department: "Engineering" },
  { employee_id: "E1003", email: "lena.ortiz@acmecorp.com", name: "Lena Ortiz", department: "Finance" }
];

const body = $input.first().json.body || $input.first().json;
const query = (body.employee_id || body.email || "").toString().trim().toLowerCase();

const match = employees.find(e =>
  e.employee_id.toLowerCase() === query || e.email.toLowerCase() === query
);

return [{
  json: match
    ? { verified: true, employee_id: match.employee_id, name: match.name, department: match.department }
    : { verified: false, message: "No employee found with that ID or email." }
}];

const body = $input.first().json.body || $input.first().json;
const ticket_id = "TCK-" + Date.now().toString().slice(-6);

return [{
  json: {
    ticket_id,
    status: "open",
    category: body.category || "general",
    summary: body.issue_summary || body.summary || "No summary provided",
    employee_id: body.employee_id || "unknown"
  }
}];

const body = $input.first().json.body || $input.first().json;
const escalation_id = "ESC-" + Date.now().toString().slice(-6);

return [{
  json: {
    escalation_id,
    status: "escalated_to_human",
    reason: body.reason || "Unresolved after automated troubleshooting",
    ticket_id: body.ticket_id || null,
    message: "You're being transferred to a live IT support agent. Reference " + escalation_id + "."
  }
}];
